(function(){
'use strict';
if(typeof ToPRGAdv==='undefined'){console.error('[RICO TEST48] ToPRGAdv missing');return;}
var TEMPLATE_B64='';
var LOAD=0x0801, SCREEN=0x4000, CHARSET=0x3000;
function decodeTemplate(){var s=atob(TEMPLATE_B64),u=new Uint8Array(s.length);for(var i=0;i<s.length;i++)u[i]=s.charCodeAt(i)&255;return u;}
function idx(addr){return 2+(addr-LOAD);}
function put(bytes,addr,v){var i=idx(addr);if(i>=0&&i<bytes.length)bytes[i]=v&255;}
function getTileSet(editor){try{var l=editor.layers.getSelectedLayerObject();if(l&&l.getType&&l.getType()==='grid'&&l.getTileSet)return l.getTileSet();return editor.tileSetManager.getCurrentTileSet();}catch(e){return null;}}
function getBank2(ts){try{var r=ts.getDocRecord&&ts.getDocRecord(),d=r&&r.data&&r.data.ricoCharsetBank2;if(d&&d.tileData&&d.tileData.length>=256)return d.tileData;}catch(e){}return null;}
function pixels(tile){return tile&&tile.data&&tile.data.length?tile.data[0]:null;}
function charsetBytes(data,fallback){var o=new Uint8Array(2048);for(var c=0;c<256;c++){var p=pixels(data&&data[c])||pixels(fallback&&fallback[c]);if(!p)continue;for(var y=0;y<8;y++){var b=0;for(var x=0;x<8;x++)if(p[y*8+x])b|=1<<(7-x);o[c*8+y]=b;}}return o;}
function cfg(editor){try{if(window.RICO_TEST37_MAP_SCROLL&&window.RICO_TEST37_MAP_SCROLL.getConfig)return window.RICO_TEST37_MAP_SCROLL.getConfig(editor.graphic,0);var f=editor.graphic.frames&&editor.graphic.frames[0],c=f&&f.ricoMapScrollV1;return c||{type:'',ticksPerStep:6,pixelsPerStep:1};}catch(e){return {type:'',ticksPerStep:6,pixelsPerStep:1};}}
function frameCount(editor){try{return editor.graphic.getFrameCount();}catch(e){return editor.graphic.frames?editor.graphic.frames.length:0;}}
function clamp(v,a,b,d){v=parseInt(v,10);return isNaN(v)?d:Math.max(a,Math.min(b,v));}
function colorIndex(v,d){v=parseInt(v,10);return isNaN(v)||v<0?d:(v&15);}
function dominantColor(layer){var h=new Array(16).fill(0);for(var y=0;y<25;y++)for(var x=0;x<40;x++){try{var c=layer.getCell({x:x,y:y,frame:0}),fc=colorIndex(c&&c.fc,14);h[fc]++;}catch(e){}}var best=14,n=-1;for(var i=0;i<16;i++)if(h[i]>n){n=h[i];best=i;}return best;}
function supports(self,args){var ed=self.editor;if(!ed||frameCount(ed)!==1)return false;var c=cfg(ed);if(c.type!=='up')return false;var l=ed.layers&&ed.layers.getSelectedLayerObject?ed.layers.getSelectedLayerObject():null;if(!l||!l.getType||l.getType()!=='grid')return false;var ts=getTileSet(ed);if(!ts||ts.getTileWidth()!=8||ts.getTileHeight()!=8)return false;var w=args&&args.gridWidth?parseInt(args.gridWidth,10):40,h=args&&args.gridHeight?parseInt(args.gridHeight,10):25;return w===40&&h===25;}
function build(self,args){var ed=self.editor,l=ed.layers.getSelectedLayerObject(),ts=getTileSet(ed),bytes=decodeTemplate(),c=cfg(ed);var frame=ed.graphic.frames&&ed.graphic.frames[0]||{};var data=ts.tileData;if(parseInt(frame.charsetBank,10)===2){var b2=getBank2(ts);if(b2)data=b2;}
var cb=charsetBytes(data,ts.tileData);bytes.set(cb,idx(CHARSET));
var si=idx(SCREEN);for(var y=0;y<25;y++)for(var x=0;x<40;x++){var t=0;try{var cell=l.getCell({x:x,y:y,frame:0});t=parseInt(cell&&cell.t,10);if(isNaN(t)||t<0||t>255)t=0;}catch(e){t=0;}bytes[si+y*40+x]=t&255;}
var bg=0,br=0;try{bg=colorIndex(l.getBackgroundColor(0),0);}catch(e){}try{br=colorIndex(l.getBorderColor(0),bg);}catch(e){br=bg;}var fg=dominantColor(l);
put(bytes,0x201f,bg);put(bytes,0x2024,br);put(bytes,0x206d,fg);
var ticks=clamp(c.ticksPerStep,1,255,4),px=clamp(c.pixelsPerStep,1,8,1);put(bytes,0x209b,ticks);put(bytes,0x209f,ticks);
// Route the proven one-pixel step through a tiny repeat wrapper so Pixels/Step 1..8 works.
put(bytes,0x20dd,0x20);put(bytes,0x20de,0xc3);put(bytes,0x20df,0x21);
var r=[0xa2,px,0x20,0xe6,0x20,0xca,0xd0,0xfa,0x60];for(var q=0;q<r.length;q++)put(bytes,0x21c3+q,r[q]);
console.log('[RICO TEST48] Standalone MAP SCROLL PRG built from proven reference runtime. ticks='+ticks+', px='+px+', bg='+bg+', fg='+fg+'.');return bytes;}
var prev=ToPRGAdv.prototype.createPRG;
ToPRGAdv.prototype.createPRG=function(args){args=args||{};if(!supports(this,args))return prev.apply(this,arguments);var bytes=build(this,args);this.prg=bytes;var fn=args.filename||'rico-map-scroll.prg';if(!/\.prg$/i.test(fn))fn+='.prg';if(args.download===false)return bytes;if(typeof window.download==='function'){window.download(bytes,fn,'application/prg');return bytes;}console.error('[RICO TEST48] download() missing');return bytes;};
window.RICO_TEST48_PRG_MAP_SCROLL=true;
console.log('[RICO TEST48] LVLLVL export path installed: single-frame 40x25 Scroll Up uses proven standalone runtime.');
})();
